package com.visualsounds;

import java.util.HashMap;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.LineComponent;

import javax.inject.Inject;
import java.awt.*;
import java.util.List;
import java.util.ArrayList;
import net.runelite.client.util.ColorUtil;

public class AmbientSoundsOverlay extends OverlayPanel {
    private static final int PANEL_WIDTH = 250;
    private static final int PANEL_BORDER = 8;
    private static final Color CONTAINER_COLOR = Color.cyan;
    private static final Color ALTERNATE_COLOR = new Color(0xFFC864);
    private static final Color GRAY_COLOR = new Color(0xA0A0A0);

    private final VisualSoundsPlugin plugin;
    public boolean displayHeader;

    @Inject
    public AmbientSoundsOverlay(VisualSoundsPlugin plugin) {
        super(plugin);

        setPosition(OverlayPosition.DYNAMIC);
        setMovable(true);
        setPosition(OverlayPosition.BOTTOM_LEFT);
        setPreferredSize(new Dimension(PANEL_WIDTH, 0));
        setLayer(OverlayLayer.UNDER_WIDGETS);
        setPriority(PRIORITY_LOW);
        this.plugin = plugin;
        displayHeader = plugin.displayOverlayHeaders;
    }

    @Override
    public Dimension render(Graphics2D graphics2D) {
        List<LayoutableRenderableEntity> renderableEntities = panelComponent.getChildren();
        renderableEntities.clear();


        if (displayHeader) {
            renderableEntities.add(
                    LineComponent.builder()
                            .left("Ambient sounds")
                            .leftColor(Color.yellow)
                            .build());
        }

        if (this.plugin.isDisabled) {
            // Show disabled message if player is in a blocked area
            renderableEntities.add(
                    LineComponent.builder()
                            .left("Plugin disabled in this area")
                            .build());
            return super.render(graphics2D);
        }

		HashMap<GameSound, GameSoundList> sounds = this.plugin.ambientSounds;
		FontMetrics metrics = graphics2D.getFontMetrics();
		// The overlay is resizable and RuneLite restores the user's saved size, so wrap to the
		// width the panel will actually be drawn at, not to our default.
		Dimension panelSize = getPreferredSize();
		int maxTextWidth = (panelSize != null ? panelSize.width : PANEL_WIDTH) - PANEL_BORDER;
		for (GameSound key : sounds.keySet()) {
			List<String[]> tokens = new ArrayList<>();
			List<GameSound> subSounds = new ArrayList<>(sounds.get(key).getGameSounds());
			boolean hasSubs = !subSounds.isEmpty();

			tokens.add(new String[]{
				ColorUtil.prependColorTag(key.label, key.color) + (hasSubs ? ColorUtil.prependColorTag(",", CONTAINER_COLOR) : ""),
				key.label + (hasSubs ? "," : "")});

			for (int i = 0; i < subSounds.size(); i++) {
				GameSound gs = subSounds.get(i);
				boolean tagged = !Color.white.equals(gs.color);
				Color color = tagged ? gs.color : (i % 2 == 0 ? GRAY_COLOR : ALTERNATE_COLOR);
				String open = i == 0 ? "[" : "";
				String close = i == subSounds.size() - 1 ? "]" : ",";
				tokens.add(new String[]{
					ColorUtil.prependColorTag(open, CONTAINER_COLOR)
						+ ColorUtil.prependColorTag(gs.label, color)
						+ ColorUtil.prependColorTag(close, CONTAINER_COLOR),
					open + gs.label + close});
			}

			// Greedy wrap between tokens: an item never gets split across lines.
			StringBuilder line = new StringBuilder();
			int lineWidth = 0;
			int spaceWidth = metrics.stringWidth(" ");
			for (String[] token : tokens) {
				int width = metrics.stringWidth(token[1]);
				if (line.length() > 0 && lineWidth + spaceWidth + width > maxTextWidth) {
					renderableEntities.add(LineComponent.builder().left(line.toString()).build());
					line.setLength(0);
					lineWidth = 0;
				}
				if (line.length() > 0) {
					line.append(' ');
					lineWidth += spaceWidth;
				}
				line.append(token[0]);
				lineWidth += width;
			}
			if (line.length() > 0) {
				renderableEntities.add(LineComponent.builder().left(line.toString()).build());
			}
		}

        return super.render(graphics2D);
    }
}

package com.visualsounds;

import java.util.Set;

/**
 * Areas where the plugin must stay disabled to comply with the
 * <a href="https://secure.runescape.com/m=news/third-party-client-guidelines?oldschool=1">third-party client guidelines</a>.
 * <p>
 * To disable the plugin in a new area, add an entry to this enum. Use https://explv.github.io to find region ids.
 * Region ids are the ones returned by {@code WorldPoint.fromLocalInstance(...).getRegionID()}, so they refer to
 * the template region when the player is inside an instance.
 */
public enum DisabledRegions
{
	ALCHEMICAL_HYDRA(Set.of(5536)),
	VARDORVIS(Set.of(4405)),
	LEVIATHAN(Set.of(8291)),
	WHISPERER(Set.of(10595)),
	SUCELLUS(Set.of(12132)),
	VORKATH(Set.of(9023)),
	INFERNO(Set.of(9043)),
	FIGHT_CAVE(Set.of(9551)),
	GAUNTLET(Set.of(7512, 7768)), // Corrupted Gauntlet, Gauntlet
	COLOSSEUM(Set.of(7216)),
	KALPHITE_QUEEN(Set.of(13972), Set.of(0)),
	COX(Set.of(
		13136, // End of floor
		13137, 13393, // Lobbies/Room transitions
		13138, 13394, // Vasa/Tekton/Vespula Lizardmen/Skeletal Mystics/Guardian
		13139, 13395, 13140, 13396, // Puzzle rooms/bosses
		13141, 13397, // Rest room
		13145, // New floor
		13401, // New floor?
		12889 // Olm
	)),
	TOB(Set.of(
		12613, // Maiden
		13125, // Bloat
		13122, // Nylocas
		13123, 13379, // Sotetseg/maze
		12612, // Xarpus
		12611 // Verzik
	)),
	TOA(Set.of(
		14160, // Nexus lobby
		15698, // Crondis
		15700, // Zebak
		14162, // Scabaras
		14164, // Kephri
		15186, // Apmeken
		15188, // Ba-Ba
		14674, // Het
		14676, // Akkha
		15184, 15696 // Wardens
	)),
	YAMA(Set.of(6045)),
	DOOM_OF_MOKHAIOTL(Set.of(5269, 13668, 14180)),
	NIGHTMARE(Set.of(15515)),
	MUSPAH(Set.of(11330)),
	MAGGOT_KING(Set.of(11645, 11901)),
	TFA(Set.of(16214, 16726, 16215, 16727, 16216, 16728, 16472, 16471));

	private final Set<Integer> regionIds;
	/**
	 * Planes the region is disabled on. Empty means every plane.
	 */
	private final Set<Integer> planes;

	DisabledRegions(Set<Integer> regionIds)
	{
		this(regionIds, Set.of());
	}

	DisabledRegions(Set<Integer> regionIds, Set<Integer> planes)
	{
		this.regionIds = regionIds;
		this.planes = planes;
	}

	private boolean matches(int regionId, int plane)
	{
		return regionIds.contains(regionId)
			&& (planes.isEmpty() || planes.contains(plane));
	}

	/**
	 * @param regionId   the region the player is currently in
	 * @param plane      the plane the player is currently on
	 * @return whether the plugin must be disabled in the given location
	 */
	public static boolean isDisabled(int regionId, int plane)
	{
		for (DisabledRegions region : values())
		{
			if (region.matches(regionId, plane))
			{
				return true;
			}
		}
		return false;
	}
}

package com.visualsounds;

import java.awt.Color;

public class GameSound {
    public final int soundId;
    public Color color;
    public String label;

    public GameSound(int soundId, Color color) {
        this.soundId = soundId;
        this.color = color;
        this.label = Integer.toString(soundId);
    }

	@Override
	public boolean equals(Object obj) {
		if (!(obj instanceof GameSound))
			return false;
		if (obj == this)
			return true;

		GameSound rhs = (GameSound) obj;
		return rhs.soundId == this.soundId
			&& rhs.color == this.color
			&& rhs.label.equals(this.label);
	}
}

package com.visualsounds;

import java.util.ArrayDeque;
import java.util.Collection;
import java.util.Collections;
import java.util.Deque;
import java.util.HashSet;
import java.util.Set;

public class GameSoundList {
    private final Deque<GameSound> gameSounds = new ArrayDeque<>();

    private int maxLength;

    /**
     * Contains the unique sound IDs within {@link #gameSounds} if deduplication should be applied
     */
    private final Set<Integer> dedupe;

    public GameSoundList(int maxLength, boolean dedupe) {
        this.maxLength = maxLength;
        if (dedupe) {
            this.dedupe = new HashSet<>();
        } else {
            this.dedupe = null;
        }
    }

    public void clear() {
        this.gameSounds.clear();
        if (this.dedupe != null) {
            this.dedupe.clear();
        }
    }

    public void add(GameSound gameSound) {
        if (dedupe != null && !dedupe.add(gameSound.soundId)) {
            return;
        }

        this.gameSounds.offerFirst(gameSound);
        this.trimToCapacity();
    }

    public Collection<GameSound> getGameSounds() {
        return Collections.unmodifiableCollection(this.gameSounds);
    }

    public void setMaxLength(int maxLength) {
        this.maxLength = maxLength;
        this.trimToCapacity();
    }

    private void trimToCapacity() {
        while (this.gameSounds.size() > maxLength) {
            GameSound evicted = this.gameSounds.removeLast();
            if (dedupe != null) {
                dedupe.remove(evicted.soundId);
            }
        }
    }

}

package com.visualsounds;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;

/**
 * Loads sound id -> name maps from JSON resources bundled with the plugin.
 */
@Slf4j
final class SoundNameLoader
{
	private static final Type MAP_TYPE = new TypeToken<Map<Integer, String>>() {}.getType();

	private SoundNameLoader()
	{
	}

	static Map<Integer, String> load(Gson gson, String resourceName)
	{
		try (InputStream in = SoundNameLoader.class.getResourceAsStream(resourceName))
		{
			if (in == null)
			{
				log.warn("Sound name resource not found: {}", resourceName);
				return Collections.emptyMap();
			}
			try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				Map<Integer, String> names = gson.fromJson(reader, MAP_TYPE);
				return names != null ? names : Collections.emptyMap();
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Failed to load sound names from {}", resourceName, e);
			return Collections.emptyMap();
		}
	}
}

